Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include<cstdio>
#include<cstring>
#include<algorithm>
#include<queue>
using namespace std;

const int MAXN=15;
const int MAXM=100005;
const int MAXNODE=MAXN*MAXN*2+5;
const int INF=1000000000;
const int dx[4]={0,0,-1,1};
const int dy[4]={1,-1,0,0};

char C[MAXN][MAXN], D[MAXN][MAXN];
int n, lim, sx, sy, S, T, tot;
int idx[MAXN][MAXN], distZ[MAXN][MAXN], visit[MAXN][MAXN];
int qarr[MAXM];
int head[MAXNODE], to[MAXM], nxt[MAXM], cap[MAXM], ecnt=1;
int preNode[MAXNODE], preEdge[MAXNODE];
int distCell[MAXN][MAXN];
struct Point { int x, y; } pointQ[MAXM];

inline bool ok(int x, int y) {
    if (x < 0 || y < 0 || x >= n || y >= n || visit[x][y] || C[x][y] < '0' || C[x][y] > '9') return 0;
    return 1;
}

void addEdge(int u, int v, int c) {
    to[++ecnt] = v; cap[ecnt] = c; nxt[ecnt] = head[u]; head[u] = ecnt;
    to[++ecnt] = u; cap[ecnt] = 0; nxt[ecnt] = head[v]; head[v] = ecnt;
}

void bfsZ() {
    int l = 1, r = 0;
    memset(distZ, 60, sizeof(distZ));
    distZ[sx][sy] = 0;
    pointQ[++r].x = sx; pointQ[r].y = sy;
    visit[sx][sy] = 1;
    for (; l <= r; ++l) {
        int ax = pointQ[l].x, ay = pointQ[l].y;
        for (int k = 0; k < 4; ++k) {
            int nx = ax + dx[k], ny = ay + dy[k];
            if (ok(nx, ny)) {
                distZ[nx][ny] = distZ[ax][ay] + 1;
                visit[nx][ny] = 1;
                pointQ[++r].x = nx; pointQ[r].y = ny;
            }
        }
    }
}

void buildLinks(int tx, int ty, int node) {
    int l = 1, r = 0;
    memset(visit, 0, sizeof(visit));
    memset(distCell, 60, sizeof(distCell));
    visit[tx][ty] = 1;
    distCell[tx][ty] = 0;
    pointQ[++r].x = tx; pointQ[r].y = ty;
    for (; l <= r; ++l) {
        int ax = pointQ[l].x, ay = pointQ[l].y;
        for (int k = 0; k < 4; ++k) {
            int nx = ax + dx[k], ny = ay + dy[k];
            if (ok(nx, ny)) {
                distCell[nx][ny] = distCell[ax][ay] + 1;
                visit[nx][ny] = 1;
                if (distCell[nx][ny] < distZ[nx][ny]) {
                    pointQ[++r].x = nx; pointQ[r].y = ny;
                }
            }
        }
    }
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (distCell[i][j] <= lim && D[i][j] > '0' && D[i][j] <= '9' && distCell[i][j] <= distZ[i][j])
                addEdge(node, idx[i][j] + tot, INF);
}

bool augmentPath() {
    memset(preNode, -1, sizeof(preNode));
    queue<int> q;
    preNode[S] = S;
    q.push(S);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int i = head[u]; i; i = nxt[i]) {
            int v = to[i];
            if (cap[i] > 0 && preNode[v] == -1) {
                preNode[v] = u;
                preEdge[v] = i;
                if (v == T) return true;
                q.push(v);
            }
        }
    }
    return false;
}

int maxflow() {
    int ans = 0;
    while (augmentPath()) {
        int add = INF;
        for (int v = T; v != S; v = preNode[v]) add = min(add, cap[preEdge[v]]);
        for (int v = T; v != S; v = preNode[v]) {
            cap[preEdge[v]] -= add;
            cap[preEdge[v] ^ 1] += add;
        }
        ans += add;
    }
    return ans;
}

int main() {
    scanf("%d%d", &n, &lim);
    for (int i = 0; i < n; ++i) scanf("%s", C[i]);
    for (int i = 0; i < n; ++i) scanf("%s", D[i]);

    for (sx = 0; sx < n; ++sx) {
        for (sy = 0; sy < n; ++sy)
            if (C[sx][sy] == 'Z') break;
        if (sy != n) break;
    }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) idx[i][j] = ++tot;

    S = 2 * tot + 1;
    T = S + 1;

    bfsZ();

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (C[i][j] > '0' && C[i][j] <= '9') {
                addEdge(S, idx[i][j], C[i][j] - '0');
                buildLinks(i, j, idx[i][j]);
            }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (D[i][j] > '0' && D[i][j] <= '9')
                addEdge(idx[i][j] + tot, T, D[i][j] - '0');

    printf("%d\n", maxflow());
    return 0;
}
